   HOST
   ========================================= */

:host {

  /* =======================================
     BALINA UI DESIGN TOKENS
     ======================================= */

  --date-width:
    300px;

  --date-height:
    44px;

  --date-background:
    #ffffff;

  --date-border:
    1px solid #a9a9a9;

  --date-border-hover:
    #777777;

  --date-border-focus:
    #68479b;

  --date-radius:
    6px;

  --date-text:
    #222222;

  --date-placeholder:
    #777777;

  --date-primary:
    #68479b;

  --date-hover:
    #f3f0f7;

  --date-selected:
    #68479b;

  --date-selected-text:
    #ffffff;

  --date-font-family:
    Arial,
    Helvetica,
    sans-serif;

  --date-font-size:
    14px;

  --date-font-weight:
    600;

  --date-shadow:
    0 4px 12px
    rgba(0, 0, 0, 0.12);

  --date-icon-color:
    #555555;

  --date-disabled-background:
    #f5f5f5;

  --date-disabled-border:
    #d0d0d0;

  --date-disabled-text:
    #999999;


  /* =======================================
     HOST
     ======================================= */

  display: block;

  position: relative;

  width:
    var(--date-width);

  box-sizing: border-box;

  font-family:
    var(--date-font-family);
}


/* =========================================
   CONTAINER
   ========================================= */

.date-input-container {

  position: relative;

  width: 100%;

  box-sizing: border-box;
}


/* =========================================
   FIELD
   ========================================= */

.date-input-field {

  position: relative;

  width: 100%;

  height:
    var(--date-height);

  display: flex;

  align-items: center;

  box-sizing: border-box;

  padding:
    0 50px 0 18px;

  border:
    var(--date-border);

  border-radius:
    var(--date-radius);

  background:
    var(--date-background);

  color:
    var(--date-text);

  font-size:
    var(--date-font-size);

  font-weight:
    var(--date-font-weight);

  cursor: pointer;

  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease,
    background-color 0.2s ease;
}


/* =========================================
   HOVER
   ========================================= */

.date-input-field:hover {

  border-color:
    var(--date-border-hover);
}


/* =========================================
   OPEN
   ========================================= */

.date-input-open
.date-input-field {

  border-color:
    var(--date-border-focus);

  box-shadow:
    0 0 0 1px
    rgba(104, 71, 155, 0.12);
}


/* =========================================
   LABEL
   ========================================= */

.date-input-label {

  position: absolute;

  top: 0;

  left: 14px;

  transform:
    translateY(-50%);

  padding:
    0 6px;

  background:
    var(--date-background);

  color:
    var(--date-border-focus);

  font-size:
    13px;

  font-weight:
    500;

  line-height:
    1;

  pointer-events:
    none;
}


/* =========================================
   VALUE
   ========================================= */

.date-input-value {

  overflow:
    hidden;

  white-space:
    nowrap;

  text-overflow:
    ellipsis;

  color:
    var(--date-text);
}


/* =========================================
   PLACEHOLDER
   ========================================= */

.date-input-placeholder {

  color:
    var(--date-placeholder);
}


/* =========================================
   CALENDAR ICON
   ========================================= */

.calendar-icon {

  position: absolute;

  right: 17px;

  width: 18px;

  height: 18px;

  box-sizing: border-box;

  border:
    1.8px solid
    var(--date-icon-color);

  border-radius: 3px;
}


/* =========================================
   CALENDAR TOP
   ========================================= */

.calendar-top {

  position: absolute;

  left: 0;

  top: 4px;

  width: 100%;

  border-top:
    1.8px solid
    var(--date-icon-color);
}


/* =========================================
   CALENDAR RINGS
   ========================================= */

.calendar-icon::before,
.calendar-icon::after {

  content: '';

  position: absolute;

  top: -4px;

  width: 2px;

  height: 6px;

  background:
    var(--date-icon-color);

  border-radius: 2px;
}


.calendar-icon::before {

  left: 4px;
}


.calendar-icon::after {

  right: 4px;
}


/* =========================================
   DATE PICKER
   ========================================= */

.date-picker {

  position: absolute;

  top:
    calc(100% + 6px);

  left: 0;

  width: 100%;

  min-width: 300px;

  z-index: 1000;

  padding: 14px;

  box-sizing: border-box;

  background:
    #ffffff;

  border:
    1px solid #d5d5d5;

  border-radius:
    var(--date-radius);

  box-shadow:
    var(--date-shadow);
}


/* =========================================
   HEADER
   ========================================= */

.date-picker-header {

  display: flex;

  align-items: center;

  justify-content: space-between;

  margin-bottom: 14px;
}


/* =========================================
   MONTH TITLE
   ========================================= */

.month-title {

  font-size:
    15px;

  font-weight:
    700;

  color:
    var(--date-text);
}


/* =========================================
   MONTH BUTTON
   ========================================= */

.month-button {

  width: 32px;

  height: 32px;

  display: flex;

  align-items: center;

  justify-content: center;

  border: none;

  border-radius: 50%;

  background: transparent;

  color: #555555;

  font-size: 24px;

  line-height: 1;

  cursor: pointer;

  transition:
    background-color 0.15s ease,
    color 0.15s ease;
}


/* =========================================
   MONTH BUTTON HOVER
   ========================================= */

.month-button:hover {

  background:
    var(--date-hover);

  color:
    var(--date-primary);
}


/* =========================================
   WEEK DAYS
   ========================================= */

.week-days {

  display: grid;

  grid-template-columns:
    repeat(7, 1fr);

  margin-bottom: 6px;

  text-align: center;

  color: #777777;

  font-size: 12px;

  font-weight: 600;
}


/* =========================================
   CALENDAR DAYS
   ========================================= */

.calendar-days {

  display: grid;

  grid-template-columns:
    repeat(7, 1fr);

  gap: 4px;
}


/* =========================================
   CALENDAR DAY
   ========================================= */

.calendar-day {

  width: 100%;

  aspect-ratio: 1;

  display: flex;

  align-items: center;

  justify-content: center;

  border: none;

  border-radius: 50%;

  background: transparent;

  color:
    var(--date-text);

  font-family:
    var(--date-font-family);

  font-size:
    13px;

  cursor: pointer;

  transition:
    background-color 0.15s ease,
    color 0.15s ease;
}


/* =========================================
   DAY HOVER
   ========================================= */

.calendar-day:hover {

  background:
    var(--date-hover);
}


/* =========================================
   OTHER MONTH
   ========================================= */

.calendar-day.other-month {

  color:
    #c0c0c0;
}


/* =========================================
   TODAY
   ========================================= */

.calendar-day.today {

  border:
    1px solid
    var(--date-primary);

  color:
    var(--date-primary);
}


/* =========================================
   SELECTED
   ========================================= */

.calendar-day.selected {

  background:
    var(--date-selected);

  color:
    var(--date-selected-text);

  border:
    none;
}


/*
 * Selected + today:
 * selected state should have priority.
 */

.calendar-day.selected.today {

  background:
    var(--date-selected);

  color:
    var(--date-selected-text);
}


/* =========================================
   DISABLED
   ========================================= */

.date-input-disabled
.date-input-field {

  background:
    var(--date-disabled-background);

  border-color:
    var(--date-disabled-border);

  color:
    var(--date-disabled-text);

  cursor:
    not-allowed;
}


/* =========================================
   RESPONSIVE
   ========================================= */

@media (max-width: 768px) {

  :host {

    width: 100%;
  }

  .date-picker {

    min-width: 100%;
  }
}

