  --textbox-disabled-color:
    #999999;

  --textbox-disabled-border:
    #d0d0d0;

  --textbox-icon-color:
    #777777;

  --textbox-icon-hover-color:
    #333333;


  /* =======================================
     HOST SIZE
     ======================================= */

  display: block;

  width:
    var(--textbox-width);

  height:
    var(--textbox-height);

  box-sizing: border-box;
}


/* =========================================
   CONTAINER
   ========================================= */

.text-box-container {

  width: 100%;

  height: 100%;

  display: flex;

  align-items: center;

  box-sizing: border-box;
}


/* =========================================
   INPUT WRAPPER
   ========================================= */

.text-box-input-wrapper {

  position: relative;

  width: 100%;

  height: 100%;

  display: flex;

  align-items: center;

  box-sizing: border-box;
}


/* =========================================
   INPUT
   ========================================= */

.text-box-input {

  width: 100%;

  height: 100%;

  box-sizing: border-box;

  padding:
    var(--textbox-padding);

  border:
    var(--textbox-border);

  border-radius:
    var(--textbox-radius);

  outline: none;

  background:
    var(--textbox-background);

  color:
    var(--textbox-text-color);

  font-family:
    var(--textbox-font-family);

  font-size:
    var(--textbox-font-size);

  font-weight:
    var(--textbox-font-weight);

  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease,
    background-color 0.2s ease;

  cursor: text;
}


/* =========================================
   PASSWORD INPUT
   ========================================= */

.text-box-input[type="password"] {

  padding-right: 48px;
}


/* =========================================
   PLACEHOLDER
   ========================================= */

.text-box-input::placeholder {

  color:
    var(--textbox-placeholder-color);

  opacity: 1;

  font-family:
    var(--textbox-font-family);

  font-size:
    var(--textbox-font-size);

  font-weight:
    var(--textbox-font-weight);
}


/* =========================================
   HOVER
   ========================================= */

.text-box-input:hover:not(:disabled) {

  border-color:
    var(--textbox-border-hover);
}


/* =========================================
   FOCUS
   ========================================= */

.text-box-input:focus {

  border-color:
    var(--textbox-border-focus);

  box-shadow:
    var(--textbox-focus-shadow);
}


/* =========================================
   DISABLED
   ========================================= */

